using Servicio.RetazoMarket.Business.DTOs.Producto;using Servicio.RetazoMarket.Business.Exceptions;using Servicio.RetazoMarket.Business.Interfaces;using Servicio.RetazoMarket.Business.Mappers;using Servicio.RetazoMarket.Business.Validators;using Servicio.RetazoMarket.DataManagment.Interfaces;using Servicio.RetazoMarket.DataManagment.Models;using Servicio.RetazoMarket.DataManagment.Models.Common;
namespace Servicio.RetazoMarket.Business.Services;public class ProductoMarketplaceService:IProductoMarketplaceService {private readonly IProductoDataService _data;public ProductoMarketplaceService(IProductoDataService data)=>_data=data;public async Task<ProductoMarketplaceResponse?> ObtenerPorIdAsync(int id,CancellationToken ct=default){var m=await _data.ObtenerPorIdAsync(id,ct);return m is null||m.prod_estado!="ACT"?null:ProductoMarketplaceBusinessMapper.ToResponse(m);}public async Task<DataPagedResult<ProductoMarketplaceResponse>> BuscarAsync(ProductoMarketplaceFiltroRequest f,CancellationToken ct=default){var e=ProductoMarketplaceValidator.Validar(f);if(e.Any())throw new ValidationException("Filtro inválido.",e);var r=await _data.BuscarAsync(new ProductoFiltroDataModel{nombre=f.nombre?.Trim(),id_linea=f.id_linea,estado="ACT",es_personalizable=f.es_personalizable?.Trim().ToUpperInvariant(),tiene_descuentos=f.tiene_descuentos?.Trim().ToUpperInvariant(),conStock=f.con_stock,precioMinimo=f.precio_minimo,precioMaximo=f.precio_maximo,PageNumber=f.page_number,PageSize=f.page_size},ct);return new(){Items=r.Items.Select(ProductoMarketplaceBusinessMapper.ToResponse).ToList(),PageNumber=r.PageNumber,PageSize=r.PageSize,TotalRecords=r.TotalRecords};}}
